 }
 $(function(){
	//文件上传
	vueParams.ajaxUpload = new Ajax_upload("#scwj", {
			action : serviceAddr+"file/upload.do",
			data: {"ywdm":"common","wjlb":"wjmb"}, 
			name : ''file'',
			autoSubmit : true,
			responseType:''json'',
			onSubmit : function(file, ext) {
				var type = ext[0];
				if($(this._input).prop("files")[0].size>30*1024*1024){
					layer.msg("文件大小超过30M", { 
						time: 1500,    	   		
						icon:6
					});
					return false;
				}
				if (!(type && /^(xlsx|xls|txt)$/.test(type.toLowerCase()))) {
					layer.msg("文件格式不正确，仅支持xlsx,xls,txt格式", { 
						time: 1500,    	   		
						icon:6
					});
					return false;
				}
				this.disable();
				vueParams.loadindex = layer.load(0,{
					shade: [0.3]
				});
			},
			onComplete : function(file, resp) {
				this.enable();
				if (!resp.status) {
					layer.msg(resp.msg, { 
						time: 1500,    	   		
						icon:6
					});
