                 whereStr = whereStr + su.addInput(field.zddm,obj[field.zddm]);
     }else if("suggest"==field.kjlx){
                 mu.safeAddToMap(obj,field.zddm,"%"+obj[field.zddm+"_text"]+"%");
                 whereStr = whereStr + su.addInput(field.zddm,obj[field.zddm]);
     }else if("time"==field.kjlx){
           whereStr = whereStr + su.addEqDate(field.zddm,obj);
     }else{
          //默认处理方式
         if(!isEmpty(obj[field.zddm])){
                 mu.safeAddToMap(obj,field.zddm,"%"+obj[field.zddm]+"%");
                 whereStr = whereStr + su.addInput(field.zddm,obj[field.zddm]);
          }
     }
 }
 var orderBy = su.addPxField(sjdx.mrpx,obj);
 mu.safeAddToMap(obj,"whereStr",whereStr);
 mu.safeAddToMap(obj,"orderBy",orderBy);
 //要上天，逆天的操作
 //db.update(db.use(),"insert into test_sjgl_1(xm) select to_char(sysdate,''yyyymmddhh24miss'') from dual",null);
*/
select * from ${owner}.${tableName} t where 1 = 1 ${whereStr} ${orderBy }
', null, null, null, 'SYS_SJGL_APPCONFIG', null, null, null, null, '1');
