${sjdx.dxgs}.${sjdx.jtdx} 
/*}else{*/
${sjdx.jtdx} 
/*}*/
where ${sjdx.zjzd} = #yobj.${sjdx.zjzd}#', null, 'SELECT *FROM 
/*IF(!ISEMPTY(SJDX.DXGS)){*/
${SJDX.DXGS}.${SJDX.JTDX} 
/*}ELSE{*/
${SJDX.JTDX} 
/*}*/
WHERE ${SJDX.ZJZD} = #YOBJ.${SJDX.ZJZD}#', 'SELECT *FROM 
/*IF(!ISEMPTY(SJDX.DXGS)){*/
${SJDX.DXGS}.${SJDX.JTDX} 
/*}ELSE{*/
${SJDX.JTDX} 
/*}*/
WHERE ${SJDX.ZJZD} = #YOBJ.${SJDX.ZJZD}#', 'SYS_SJGL_APPCONFIG', null, null, null, null, '1');

